def encode_decode(strs):
    def encode(strings):
        encoded = []
        for s in strings:
            encoded.append(str(len(s)) + "#" + s)
        return "".join(encoded)

    def decode(s):
        result = []
        i = 0
        while i < len(s):
            j = i
            while s[j] != "#":
                j += 1
            length = int(s[i:j])
            start = j + 1
            result.append(s[start:start + length])
            i = start + length
        return result

    encoded = encode(strs)
    return decode(encoded)

